"use strict";
  function statusText(s){return ({approved:"Публикувано",pending:"Чака преглед",needs_changes:"За корекция",rejected:"Отказано"})[s]||s}
  function statusRows(items,type){return items.length?`<div class="status-list">${items.map((x,i)=>`<div class="status-item"><div><h3>${esc(x.title)}</h3><p>${esc(type)} · ${esc(statusText(x.status))}</p></div><div class="flex">${statusBadge(x.status)}${x.status==="needs_changes"?`<button class="button button-soft" type="button" data-action="profile-edit" data-kind="${esc(type)}">Коригирай</button>`:""}</div></div>`).join("")}</div>`:`<div class="empty-state"><h2>Няма съдържание</h2><p>Когато добавиш нещо, статусът му ще се вижда тук.</p></div>`}
  function reviewRoleLabel(){return isAdmin()?"Администратор":isModerator()?"Модератор":"Потребител"}
  function renderProfile(){if(!signedIn())return renderSignedOutProfile();const tabs=[['summary','Обобщение'],['listings','Моите обяви'],['firms','Моите фирми'],['questions','Моите въпроси'],['corrections','Корекции']];const tab=state.profileTab||"summary";let body="";if(tab==="summary")body=`<div class="grid grid-3"><div class="count-card"><span class="muted">Обяви</span><b>${D.profile.listings.length}</b></div><div class="count-card"><span class="muted">Фирми</span><b>${D.profile.firms.length}</b></div><div class="count-card"><span class="muted">Въпроси</span><b>${D.profile.questions.length}</b></div></div><div class="detail-block mt-16"><h2>Нуждаят се от действие</h2>${statusRows([...D.profile.listings,...D.profile.firms].filter(x=>x.status==="needs_changes"),"Съдържание")}</div>`;if(tab==="listings")body=statusRows(D.profile.listings,"Обява");if(tab==="firms")body=statusRows(D.profile.firms,"Фирма");if(tab==="questions")body=statusRows(D.profile.questions,"Въпрос");if(tab==="corrections")body=statusRows(D.profile.corrections,"Корекция");main.innerHTML=pageIntro("Профил",D.profile.name,`${D.profile.email} · Роля за преглед: ${reviewRoleLabel()}`,`${isAdmin()||isModerator()?button(isAdmin()?"Администраторски панел":"Модераторски панел","admin","button button-soft"):""}<button class="button button-outline" type="button" data-action="logout">Изход</button>`)+`<section class="section"><div class="shell profile-summary"><nav class="profile-nav">${tabs.map(([k,l])=>`<button class="${tab===k?"active":""}" data-profile-tab="${k}">${l}</button>`).join("")}</nav><div>${body}</div></div></section>`}
  function renderSignedOutProfile(){main.innerHTML=pageIntro("Профил","Влез в Попитай.Лом","След вход виждаш своите обяви, фирми, въпроси, корекции и състоянията им.")+`<section class="section"><div class="shell"><div class="auth-card form-card"><h2>Нямаш активна сесия</h2><p>В прототипа можеш да прегледаш входа и регистрацията. Реални акаунти не се създават.</p><div class="grid grid-2"><button class="button button-primary" data-route="auth/login">Вход</button><button class="button button-soft" data-route="auth/register">Регистрация</button></div></div></div></section>`}
  function renderAuth(kind){if(kind==="register")return renderRegister();if(kind==="recover")return renderRecover();main.innerHTML=pageIntro("Профил","Вход","Влез, за да публикуваш, редактираш и следиш своето съдържание.")+`<section class="section"><div class="shell"><div class="auth-card form-card"><form class="form-grid proto-form" data-form="login">${field("Електронна поща","email",{required:true,type:"email",autocomplete:"email",full:true})}${field("Парола","password",{required:true,type:"password",min:8,autocomplete:"current-password",full:true})}<div class="form-actions"><button type="button" class="button button-outline" data-route="auth/recover">Забравена парола</button><button class="button button-primary" type="submit">Вход</button></div></form><div class="auth-links"><button data-route="auth/register">Нямаш профил? Регистрация</button></div></div></div></section>`;bindFormUX()}
  function renderRegister(){main.innerHTML=pageIntro("Стани част от общността","Регистрация","Създай безплатен профил. В този прототип регистрацията е само симулация.")+`<section class="section"><div class="shell"><div class="auth-card form-card"><form class="form-grid proto-form" data-form="register">${field("Име","name",{required:true,min:2,autocomplete:"name",full:true})}${field("Електронна поща","email",{required:true,type:"email",autocomplete:"email",full:true})}${field("Парола","password",{required:true,type:"password",min:8,autocomplete:"new-password",full:true})}${field("Повтори паролата","confirm_password",{required:true,type:"password",min:8,autocomplete:"new-password",full:true})}<label class="check-row field-full"><input type="checkbox" name="consent" required> Приемам условията и политиката за поверителност.</label><div class="form-actions"><button class="button button-outline" type="button" data-route="auth/login">Имам профил</button><button class="button button-primary" type="submit">Създай профил</button></div></form></div></div></section>`;bindFormUX()}
  function renderRecover(){main.innerHTML=pageIntro("Профил","Възстановяване на парола","Въведи електронната си поща. Прототипът симулира изпращането на инструкции.")+`<section class="section"><div class="shell"><div class="auth-card form-card"><form class="form-grid proto-form" data-form="recover">${field("Електронна поща","email",{required:true,type:"email",autocomplete:"email",full:true})}<div class="form-actions"><button class="button button-outline" type="button" data-route="auth/login">Назад към вход</button><button class="button button-primary" type="submit">Изпрати инструкции</button></div></form></div></div></section>`;bindFormUX()}

  function renderOfferRequest(){const r=routeInfo(),id=r.params.get("firm"),f=D.firms.find(x=>x.id===id);if(!f)return renderNotFound();main.innerHTML=pageIntro("Контакт с фирма","Поискай оферта",`До: ${f.name}. Тук преглеждаме как трябва да изглежда бъдещото запитване, без да променяме текущата логика за фирмите.`)+`<section class="section"><div class="shell form-wrap"><div class="form-card"><div class="notice notice-info"><strong>Само за преглед</strong>Истинското изпращане на запитване е отделна следваща задача. Тази форма не изпраща данни към основния сайт.</div><form class="form-grid proto-form mt-16" data-form="offer-request">${field("Име","name",{required:true,min:2})}${field("Телефон","phone",{required:true,type:"tel"})}${field("Електронна поща (по желание)","email",{type:"email"})}${selectField("Предпочитан контакт","contact_method",["Телефон","Електронна поща"],"Телефон",{required:true})}${field("Каква работа ти трябва?","details",{textarea:true,required:true,min:20,full:true})}${field("Населено място / район","area",{required:true,min:2,full:true,value:"Лом"})}<div class="form-actions"><button class="button button-outline" type="button" data-route="firm/${f.id}">Отказ</button><button class="button button-primary" type="submit">Изпрати запитване</button></div></form></div></div></section>`;bindFormUX()}

  function renderReport(){const r=routeInfo(),target=r.params.get("target")||"съдържание",owner=r.params.get("owner")||"generic";main.innerHTML=pageIntro("Сигнал","Докладвай проблем",`Сигнал за: ${target}. Общият сигнал е различен от „Предложи корекция“ при проверената информация.`)+`<section class="section"><div class="shell form-wrap"><div class="form-card"><form class="form-grid proto-form" data-form="report"><input type="hidden" name="target" value="${esc(target)}"><input type="hidden" name="owner" value="${esc(owner)}">${selectField("Причина","reason",["Неподходящо съдържание","Подвеждаща информация","Спам","Нарушение на правилата","Друго"],"",{required:true,full:true})}${field("Опиши проблема","details",{textarea:true,required:true,min:10,full:true})}<div class="form-actions"><button class="button button-outline" type="button" data-route="home">Отказ</button><button class="button button-primary" type="submit">Изпрати сигнал</button></div></form></div></div></section>`;bindFormUX()}

  function renderAdmin(){if(!isAdmin()&&!isModerator()){main.innerHTML=pageIntro("Защитена зона","Панел за управление","Този екран се показва само при разрешена роля.")+`<section class="section"><div class="shell"><div class="notice notice-danger"><strong>Нямаш достъп</strong>Смени ролята от „Прототип“ само за да прегледаш как изглеждат разрешените функции за съответната роля.</div></div></section>`;return}const tab=state.adminTab||"dashboard";const total=Object.values(D.adminCounts).reduce((a,b)=>a+b,0);let work="";if(tab==="dashboard")work=`<div class="admin-top"><div><h2 class="mt-0">Начало</h2><p class="muted mt-0">Задачи за преглед според ролята.</p></div><span class="badge badge-danger">${total} задачи</span></div><div class="grid admin-counts">${Object.entries(D.adminCounts).filter(([,n])=>n>0).map(([k,n])=>`<button class="count-card" type="button" data-admin-tab="review"><span class="muted">${esc(({listings:"Обяви",firms:"Фирми",shops:"Магазини",info:"Инфо Лом",reports:"Сигнали",edits:"Редакции",expanded:"Разширени профили",events:"Събития"})[k]||k)}</span><b>${n}</b><small>Отвори за преглед</small></button>`).join("")}</div><div class="detail-block mt-16"><h2>Правила на ролята</h2>${isModerator()?`<div class="notice notice-warn"><strong>Модератор</strong>Може да преглежда чуждо съдържание, но не и собственото си. Няма право на окончателно изтриване, управление на роли, даване или отнемане на разширен достъп и директно публикуване като администратор.</div>`:`<div class="notice notice-ok"><strong>Администратор</strong>Вижда защитените административни функции, директното публикуване и управлението на разширен достъп според каноничните правила.</div>`}</div>`;if(tab==="review")work=`<div class="admin-top"><div><h2 class="mt-0">За преглед</h2><p class="muted mt-0">Само задачи, които текущата роля има право да обработи.</p></div><span class="badge badge-danger">${D.adminQueue.length} показани</span></div>${D.adminQueue.map(x=>`<div class="queue-item"><div><span class="owner-label">${esc(x.type)}</span><strong>${esc(x.title)}</strong><div class="muted small">Подадено от: ${esc(x.owner)}</div></div><div class="queue-actions"><button class="button button-soft" data-action="review-open">Преглед</button><button class="button button-primary" data-action="review-approve">Одобри</button><button class="button button-outline" data-action="review-return">Върни за корекция</button><button class="button button-danger" data-action="review-hide">Скрий / откажи</button>${isAdmin()?`<button class="button button-danger" data-action="admin-hard-delete">Окончателно изтрий</button>`:""}</div></div>`).join("")}`;if(tab==="content")work=`<div class="admin-top"><div><h2 class="mt-0">Съдържание</h2><p class="muted mt-0">Публикувано и управлявано съдържание.</p></div></div><div class="grid grid-3"><div class="count-card"><span>Публикувани въпроси</span><b>${D.questions.length}</b></div><div class="count-card"><span>Обяви</span><b>${D.listings.filter(x=>x.status==="approved").length}</b></div><div class="count-card"><span>Фирми</span><b>${D.firms.length}</b></div><div class="count-card"><span>Магазини</span><b>${D.shops.length}</b></div><div class="count-card"><span>Събития</span><b>${D.events.length}</b></div><div class="count-card"><span>Инфо Лом</span><b>${D.infoRecords.length}</b></div></div>`;if(tab==="management")work=`<div class="admin-top"><div><h2 class="mt-0">Управление</h2><p class="muted mt-0">Функции, които се показват според разрешената роля.</p></div></div>${isAdmin()?`<div class="grid grid-3"><button class="card compact-card" data-action="admin-manage-roles"><h3>Роли</h3><p>Само за администратора.</p></button><button class="card compact-card" data-action="admin-expanded"><h3>Разширен достъп</h3><p>Дава се или се отнема само от администратора.</p></button><button class="card compact-card" data-action="admin-system"><h3>Системно управление</h3><p>Защитени административни функции.</p></button></div>`:`<div class="notice notice-info"><strong>Модератор</strong>Тук не се показват управление на роли, окончателно изтриване или даване и отнемане на разширен достъп.</div>`}`;main.innerHTML=pageIntro("Работна среда",isAdmin()?"Администраторски панел":"Модераторски панел","Отделна работна среда за преглед и управление на съдържанието.",button("Към сайта","home"))+`<section class="section"><div class="shell"><div class="admin-shell"><aside class="admin-sidebar"><strong>Попитай.Лом</strong><small>${isAdmin()?"Администратор":"Модератор"}</small><nav><button class="${tab==="dashboard"?"active":""}" data-admin-tab="dashboard">Начало</button><button class="${tab==="review"?"active":""}" data-admin-tab="review">За преглед</button><button class="${tab==="content"?"active":""}" data-admin-tab="content">Съдържание</button><button class="${tab==="management"?"active":""}" data-admin-tab="management">Управление</button></nav></aside><div class="admin-work">${work}</div></div></div></section>`}

  const staticPages={
    about:{k:"За общността",t:"За Попитай.Лом",p:"Местен продукт за Лом: намиране на услуги, обяви, фирми, проверена информация и полезни препоръки.",body:["Целта е човек да стига бързо до правилния източник и вид съдържание.","Обявите са временни. Фирмите са постоянни профили. Инфо Лом е проверена справочна информация. Въпросите са общностен слой."]},
    rules:{k:"Правила",t:"Правила на общността",p:"Ясни правила за полезно и безопасно местно съдържание.",body:["Публикувай вярна и конкретна информация.","Не публикувай чужди лични данни без основание.","Не използвай подвеждащи заглавия, спам или фалшиви препоръки.","Модерацията и одобрението следват ролите и правилата за съответния вид съдържание."]},
    privacy:{k:"Правна информация",t:"Поверителност",p:"Прототипна повърхност за одобрената политика за поверителност.",body:["Окончателният текст остава този в реалния сайт и неговите одобрени документи.","Този прототип не изпраща лични данни към основния сайт."]},
    terms:{k:"Правна информация",t:"Условия за ползване",p:"Прототипна повърхност на условията за ползване.",body:["Потребителят носи отговорност за съдържанието, което подава.","Публичността зависи от вида съдържание и състоянието на прегледа."]},
    cookies:{k:"Правна информация",t:"Бисквитки",p:"Прототипна повърхност за настройките и информацията за бисквитки.",body:["Изолираният прототип пази само необходимите локални настройки за преглед на роли и състояния.","Не зарежда системата за анализ на основния сайт и не изпраща данни към него."]}
  };
  function renderStaticPage(key){const x=staticPages[key];if(!x)return renderNotFound();main.innerHTML=pageIntro(x.k,x.t,x.p)+`<section class="section"><div class="shell form-wrap"><div class="detail-block"><h2>${esc(x.t)}</h2>${x.body.map(p=>`<p>${esc(p)}</p>`).join("")}</div></div></section>`}
  function renderContact(){main.innerHTML=pageIntro("Връзка с нас","Контакти","Изпрати общо съобщение. За проблем със съдържание използвай „Подай сигнал“, а за факт в Инфо Лом — „Предложи корекция“.")+`<section class="section"><div class="shell form-wrap"><div class="form-card"><form class="form-grid proto-form" data-form="contact">${field("Име","name",{required:true,min:2})}${field("Електронна поща","email",{required:true,type:"email"})}${field("Тема","subject",{required:true,min:3,full:true})}${field("Съобщение","message",{textarea:true,required:true,min:20,full:true})}<div class="form-actions"><span class="muted small">Прототип — не изпраща реално.</span><button class="button button-primary" type="submit">Изпрати</button></div></form></div></div></section>`;bindFormUX()}
